<script setup lang="ts">import { ref, watch } from 'vue'; import { getPublicCompetition } from '@/services/schoolAdminApi'; const props=defineProps<{publicIdentifier:string;competitionPublicKey:string}>(); const item=ref<any>(null); const unavailable=ref(false); async function load(){item.value=null;unavailable.value=false;try{item.value=await getPublicCompetition(props.publicIdentifier,props.competitionPublicKey)}catch{unavailable.value=true}} watch(()=>[props.publicIdentifier,props.competitionPublicKey],load,{immediate:true});</script><template><main><section v-if="unavailable"><h1>Competition unavailable</h1></section><template v-else-if="item"><h1>{{item.name}}</h1><RouterLink v-for="fixture in item.fixtures" :key="fixture.public_identifier" :to="fixture.canonical_path">{{fixture.team_a_name}} vs {{fixture.team_b_name}}</RouterLink></template></main></template>
